// ── MITRE tactic keyword match score ─────────────────────────────────────────

function matchScore(tactic: MitreTactic, item: ThreatItem): number {
  const hay = `${item.title} ${item.excerpt || ""} ${item.category || ""}`.toLowerCase();
  return tactic.keywords.reduce((n, kw) => n + (hay.includes(kw) ? 1 : 0), 0);
}

// ── Build dynamic attack chain from real feed data ───────────────────────────

function buildChain(items: ThreatItem[]): AttackStage[] {
  if (!items.length) return [];

  // Map each item to its best-matching tactic
  const tacticBuckets: Record<string, ThreatItem[]> = {};
  items.forEach(item => {
    let best: MitreTactic | null = null; let bestScore = 0;
    TACTICS.forEach(t => {
      const s = matchScore(t, item);
      if (s > bestScore) { bestScore = s; best = t; }
    });
    // Fallback: map by category
    if (!best || bestScore === 0) {
      const cat = (item.category || "").toLowerCase();
      if (cat === "ransomware" || cat === "impact") best = TACTICS.find(t => t.id === "TA0040")!;
      else if (cat === "malware") best = TACTICS.find(t => t.id === "TA0002")!;
      else if (cat === "vulnerability") best = TACTICS.find(t => t.id === "TA0001")!;
      else if (cat === "threat-intel") best = TACTICS.find(t => t.id === "TA0001")!;
      else best = TACTICS.find(t => t.id === "TA0001")!;
    }
    const id = best!.id;
    if (!tacticBuckets[id]) tacticBuckets[id] = [];
    tacticBuckets[id].push(item);
  });

  // Build stages in kill-chain order
  const stages: AttackStage[] = [];
  const SEV_RANK: Record<string, number> = { critical: 0, high: 1, medium: 2, low: 3 };

  TACTIC_ORDER.forEach(tacticId => {
    const bucket = tacticBuckets[tacticId];
    if (!bucket?.length) return;

    const tactic  = TACTICS.find(t => t.id === tacticId)!;
    const flow    = TACTIC_FLOW[tacticId] ?? { from: "laptop", to: "laptop" };
    // Pick highest-severity representative item
    bucket.sort((a, b) => (SEV_RANK[a.severity] ?? 3) - (SEV_RANK[b.severity] ?? 3));
    const item = bucket[0];

    // Extract real IOCs
    const iocs: IOC[] = [];
    (item.iocs?.ipv4 || []).slice(0, 3).forEach(ip => iocs.push({ type: "ip", value: ip }));
    (item.iocs?.sha256 || []).slice(0, 2).forEach(h => iocs.push({ type: "sha256", value: h.slice(0, 24) + "…" }));
    (item.iocs?.domains || []).slice(0, 3).forEach(d => iocs.push({ type: "domain", value: d }));
    (item.iocs?.cves || []).slice(0, 3).forEach(c => iocs.push({ type: "cve", value: c }));
    if (iocs.length === 0) iocs.push({ type: "source", value: item.source_name });

    // Best-matching technique name from tactic
    const techStr  = tactic.techniques[0] ?? tactic.name;
    const techParts = techStr.split(" ");
    const techId   = techParts[0];
    const techName = techParts.slice(1).join(" ");

    stages.push({
      id: tacticId, name: tactic.name, color: tactic.color,
      from: flow.from, to: flow.to,
      mitre: { tactic: tactic.name, tacticId, technique: techName, techId },
      iocs,
      description: item.excerpt?.slice(0, 350) || item.title,
      source: item.source_name, severity: item.severity,
      link: item.link, publishedAt: item.published_at,
      matchCount: bucket.length, duration: 1800,
    });
  });

  return stages;
}

// ── Infra helpers ─────────────────────────────────────────────────────────────

function buildGeometry(type: string): THREE.BufferGeometry {
  switch (type) {
    case "firewall":  return new THREE.CylinderGeometry(0.45, 0.45, 0.18, 8);
    case "laptop":    return new THREE.BoxGeometry(0.9, 0.12, 0.65);
    case "attacker":  return new THREE.OctahedronGeometry(0.42, 0);
    case "c2":        return new THREE.OctahedronGeometry(0.42, 0);
    case "email":     return new THREE.ConeGeometry(0.35, 0.7, 6);
    case "dc":        return new THREE.BoxGeometry(0.55, 1.0, 0.55);
    case "database":  return new THREE.CylinderGeometry(0.4, 0.4, 0.6, 16);
    default:          return new THREE.BoxGeometry(0.55, 0.75, 0.55);
  }
}

function bezierPts(a: THREE.Vector3, b: THREE.Vector3, n = 40): THREE.Vector3[] {
  if (a.distanceTo(b) < 0.1) return [a.clone()];
  const mid = a.clone().lerp(b, 0.5);
  mid.y += 1.2 + a.distanceTo(b) * 0.15;
  return new THREE.QuadraticBezierCurve3(a, mid, b).getPoints(n);
}

